INSERT INTO `SERVMASK_PREFIX_addonlibrary_addons` VALUES (1,'Animated Gradient Background','gradient_animation_bg_addon','gradient_animation','bg_addon','The Animated Gradient Background for Elementor allows you to design beautiful gradient backgrounds for your sections. Create unique effects by changing the gradient angle and applying a variety of color choices! This animate background effect can be used in your hero section or any other section on your Elementor website to your liking.',1,'{\"html\":\"<div id=\\\"{{uc_id}}\\\">\\n<\\/div>\",\"css\":\"#{{uc_id}} {\\n\\tbackground: linear-gradient({{angle_nounit}}deg, {{color_one}}, {{color_two}}, {{color_three}}, {{color_four}});\\n\\tbackground-size: 400% 400%;\\n\\tanimation: {{uc_id}}gradient {{duration}}s ease infinite;\\n\\tposition:absolute;\\n\\ttop:0px;\\n\\tleft:0px;\\n\\tbottom:0px;\\n\\tright:0px;\\n}\\n\\n@keyframes {{uc_id}}gradient {\\n\\t0% {\\n\\t\\tbackground-position: 0% 50%;\\n\\t}\\n\\t50% {\\n\\t\\tbackground-position: 100% 50%;\\n\\t}\\n\\t100% {\\n\\t\\tbackground-position: 0% 50%;\\n\\t}\\n}\"}','{\"options\":{\"enable_items\":\"false\",\"items_section_title\":\"\",\"items_section_heading\":\"\",\"items_title_field\":\"\",\"path_assets\":\"gradient_animation\",\"js_as_module\":false,\"addon_icon\":\"\",\"dynamic_addon\":\"false\",\"dynamic_post_enable_customfields\":\"false\",\"dynamic_post_enable_category\":\"false\",\"description\":\"The Animated Gradient Background for Elementor allows you to design beautiful gradient backgrounds for your sections. Create unique effects by changing the gradient angle and applying a variety of color choices! This animate background effect can be used in your hero section or any other section on your Elementor website to your liking.\",\"link_resource\":\"\",\"link_preview\":\"https:\\/\\/unlimited-elements.com\\/animated-gradient-background-widget-for-elementor\\/\",\"show_small_icon\":\"true\",\"preview_size_unite_selected_text\":\"Full Size\",\"preview_s